import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.RequestEntity;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import javax.servlet.http.HttpServletRequest;

@Controller
@RequestMapping(value = "/auth")
public class AuthController {

    private Logger logger = LoggerFactory.getLogger(this.getClass());

    @Autowired
    private UserService userService;

    @Autowired
    private TokenService tokenService;

    @GetMapping(value = "/register")
    public String registrazione(Model model) {
        model.addAttribute("action", "/auth/register");
        model.addAttribute("path", "/auth/register");
        model.addAttribute("username", "");
        return "auth/form";
    }

    @GetMapping(value = "/login")
    public String login(Model model, String username, String password) {

        RequestEntity token = tokenService.checkToken(username, password);

        if (token!= null) {
            model.addAttribute("username", username);
            return "loggedUser";
        } else {
            // 401 error
            return "login";
        }
    }

    @GetMapping(value = "/logout")
    public String logout(Model model, HttpServletRequest request) {
        String log = tokenService.extractLog(request.getHeader("Authorization"));

        String username = userService.getUsername(log);
        tokenService.delete(username);
        logger.info("Logout from user: " + username);
        return "login";
    }

}
