public class HttpUtil {
    private static final String COOKIE_NAME = "JSESSIONID";
    private static final String COOKIE_VALUE = "167A6A4B45BB08A349DEA0F00AF5631D";

    public static String call(String url) throws IOException {
        String urlContent = "";

        BufferedReader in = null;
        try {
            URL targetURL = new URL(url);
            URLConnection conn = targetURL.openConnection();
            conn.setRequestProperty("ContentType", "json/application"); // 设置参数类型
            conn.setRequestProperty("Cookie", COOKIE_NAME + "=" + COOKIE_VALUE);
            conn.setConnectTimeout(5 * 1000);
            conn.setReadTimeout(5 * 1000);
            StringBuilder postData = new StringBuilder();
            conn.setDoOutput(true);
            in = new BufferedReader(new InputStreamReader(targetURL.openStream()));
            String str;
            while ((str = in.readLine())!= null) {
                postData.append(str);
            }
            urlContent = postData.toString();
        } catch (IOException e) {
            if (StringUtils.isNotBlank(urlContent)) {
                return urlContent;
            }
            throw e;
        } finally {
            try {
                if (in!= null) {
                    in.close();
                }
            } catch (IOException e) {
                throw e;
            }
        }
        return urlContent;
    }
}
