		if (ze == null) {
			throw new Exception("Archive " + inputZipFile + " is empty!");
		}
		int index = ze.getName().lastIndexOf("/");
		int endIndex = ze.getName().lastIndexOf(".class");
		if (index < 0 || endIndex < 0 || index + 1 > endIndex) {
			throw new Exception("Member name not valid! " + ze.getName());
		}
		String className = ze.getName().substring(index + 1, endIndex);
		System.err.println(String.format("Unzipping member: %s", className));
		if (className.contains("..")) {
			throw new Exception("Member name may not contains '..'!");
		}

		if (!outputFolder.exists() &&!outputFolder.mkdirs()) {
			throw new Exception("Output folder not found! " + outputFolder);
		} else {
			File dest = new File(outputFolder, className);
			FileOutputStream output = new FileOutputStream(dest);
			int size = 0;
			while ((size = zIns.read())!= -1) {
				output.write(size);
			}
			output.close();
		}

		zIns.closeEntry();
	}
