public interface Completion {

    /**
     * Returns the name of the completion.
     * <p>
     * Every completion must have a well known name.
     */
    String getName();

    /**
     * Returns a string description of the completion.
     * <p>
     * Examples are: "type", "return type", "private method".
     */
    String getDescription();

    /**
     * Applies the completion to the code.
     */
    void apply(Code code) throws CodeGenerationException;

    /**
     * Applies the completion to the specified code visitor.
     */
    void apply(CodeVisitor visitor) throws CodeGenerationException;

    /**
     * Returns whether this completion can lead to ambiguous completions.
     * <p>
     * A completion can lead to ambiguities under two circumstances:
     * <h3>If any of the options would be an exact match for the given text</h3>
     * 
     * Example: Suppose the completion would be <b>private A</b> for text
     * <b>public C extends A</b>.
     * 
     * <h3>If the text could be matched by more than one option</h3>
     * 
     * Example: Suppose the completion would be "new A()" for text
     * <b>A extends Object { public A()</b>.
     * 
     * @return true if any of the options will lead to an ambiguous completion.
     *         false if the completion will lead to a unique match.
     */
    boolean isAmbiguous();

    /**
     * Returns all ambigous completions for possible matches at the specified
     * position.
     */
    List<Completion> getAmbigousCompletions() throws CodeGenerationException;

}
