public class ClassX {
    public static void removeElements(File inputFile, Filter<String> filter, Consumer<Document> consumer) {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setValidating(false);
        dbf.setIgnoringElementContentWhitespace(true);
        dbf.setIgnoringComments(true);
        try {
            DocumentBuilder db = dbf.newDocumentBuilder();

            Document doc = db.parse(inputFile); 

            for (Element elem : ((Node) doc).getChildNodes()
                findElements( elem )
            ) {
                elem.getParentNode().removeChild( elem );
            }

            consumer.accept(doc);
        } catch (IOException | SAXException e) {
            System.err.println(e.getMessage());
        }
    }

    private static List<Element> findElements(Node node) {
      List<Element> elements = new ArrayList<>();
        for (Node child = null; (child = node.getFirstChild())!= null; ) {
            if(matchFilter(child.getNodeName())){
                elements.add((Element)child);
            }
            elements.addAll( findElements( child ) );
            node.removeChild(child);
        }
        return elements;
    }

    private static boolean matchFilter(String name) {
        name = name.intern();

        switch( name ){
            case "style":
            case "class":
            case "id":
            case "xml":
            case "url":
            case "href":
                return true; 
            default:
                return false;
        }
    }
}
