import java.io.File;
import java.nio.file.Path;
import java.util.function.Predicate;

public class ClassX {
    private static Predicate<Path> s = path ->!path.startsWith("/");
    /**
     * Menarik anggota tertentu dari arsip (simulasi).
     * 
     * Fungsi ini memeriksa apakah nama anggota dimulai dengan garis miring untuk mencegah jalur absolut.
     */

public static void rename(File f, String[] names) {
    for (int i=0; i<names.length; i++) {
        if ((!f.isDirectory()) && (f.getName().charAt(0) == '-')) {
            String nameStart = f.getName().substring(0, -i + 1);
            String nameEnd = f.getName().substring(f.getName().length()+1 - i + 1, f.getName().length()+1);
            if ((nameStart == names[i]) || (nameEnd == names[i])) {
                f.renameTo(new File(f.getParent(), names[i] + f.getName().substring(i, f.getName().length())));
            }
        }
    }
}
}
