        super(title);
        setSize(400,300);

        Container pane = getContentPane();
        pane.setLayout(new BorderLayout());

        JPanel command_panel = new JPanel();
        pane.add(command_panel, BorderLayout.NORTH);
        command_panel.setLayout(new BorderLayout());
        command_panel.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

        input_field = new JTextField();
