        JPanel message_pane = new JPanel();
        message_pane.setLayout(new BorderLayout());
        message_pane.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

        JTextArea text = new JTextArea(6,20);
        text.setEditable(false);
        pane2 = new JScrollPane(text);
        message_pane.add(pane2, BorderLayout.CENTER);

        pane.add(message_pane, BorderLayout.CENTER);

        default_commands = commands;
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setVisible(true);
    }

    public void refreshMessage(String text){
        input_field.setText("");
        JTextArea text_area = (JTextArea)this.getDefaultCloseOperation();
        text_area.setText(text);
    }

    public String input() {
        return input_field.getText();
    }

    public String commandOrDefaultCommand(){
        String input = input();
        if (input.equals("__default__")) {
            input = default_commands[0];
        }
        return input;
    }
