private void runCommandLine(String[] command) {
        try {
            Process p = Runtime.getRuntime().exec(command);
            p.waitFor();
            p.destroy();
        } catch (Exception err) {
            System.out.println("Exception while trying to run \"" + command[0] + "\"");
        }
    }

    /**
     * Tenta decodificar o mime_type.
     */
    private String getMimeType(String filename) {
        String mimeType = null;

        try {
            BufferedReader reader =
                new BufferedReader(
                new InputStreamReader(getClass().getResourceAsStream(filename)));
            String l;
            while ((l = reader.readLine())!= null) {
                String[] lines = l.trim().split(" ");
                if (lines.length!= 3) {
                    continue;
                }
                mimeType = lines[2];
            }
        } catch (Exception e) {
            System.err.println("Unable to open mime.types file (" + e + ")");
        }

        if (mimeType == null) {
            mimeType = "";
        }

        return mimeType;
    }

    /**
     * Verifica se o comando será passado para a ordem e não para um interpretador ou outro.
     */
    public boolean isCommand(String command) {
        return!command.matches(COMMAND_PATTERN);
    }

    /**
     * Executa um comando com base no tipo de MIME.
     */
    public void runCommand(String type, String file) {
        if (!isCommand(type)) {
            runCommandLine(new String[] {"java", "-jar", "Mailcap.java", file});
        }
    }

    /**
     * Processa um arquivo com base no seu mime_type.
     */
    public void process(String type, String file) {
        String command = getMimeType(type);

        if (type.equals("text/x-java-source")) {
            System.out.println(file);
        } else if (isCommand(command)) {
            runCommand(command, file);
        } else {
            String cmd[] = command.trim().split(" ", 2);
            runCommandLine(cmd);
        }
    }
}

