public class CaseInsensitiveHashMap<K, V> extends HashMap<K, V> {
    @Override
    public V get(Object key) {
        if (containsKey(key)) {
            if (key instanceof String) {
                if (((String) key).equalsIgnoreCase((String) super.get(key))) {
                    return super.get(key);
                }
            } else {
                for (K k : super.keySet()) {
                    if (key.equals(k)) {
                        return super.get(key);
                    }
                }
            }
        }

        return null;
    }
}
