     */
    public void addNumber(int num) {
        do {
            for (int i = 0; i < column; i++) {
                if (num == lottoNumbers[num - 1][i]) {
                    System.out.println("Already used!");
                    i = 41;
                }
            }
        } while (num!= -1);
        lottoNumbers[num - 1][column - 1] = num;
    }

    /**
     * Sets the last number in the current column.
     */
    public void finishLottoColumn() {
        for (int i = column; i < 6; i++) {
            lottoNumbers[column - 1][i] = 0;
        }
        column++;
    }

    /**
     * Gets number of columns.
     * @return Number of used columns.
     */
    public int getColumn() {
        return column;
    }
