import java.io.BufferedReader;
import java.io.InputStreamReader;

import nl.cybortek.util.IO;

public class ClassX {
    /**
     * Pings 'n gespesifiseerde gasheer.
     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     */

    public static void main(String[] args) throws Exception {
        IO io = IO.getIn();
        try {
            while (true) {
                io.print("> ");
                String input = io.inp().trim();

                for (int i = 0; i < input.length(); i++) {
                    char c = input.charAt(i);
                    if (c == '.' || c =='' || c == '+') {
                        input = input.substring(0, i) + "%" + Integer.toHexString(c) + "%" +
                                input.substring(i + 1);
                        i += 3;
                    }
                }

                for (int i = 0; i < input.length(); i++) {
                    char c = input.charAt(i);
