import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;
import pl.edu.agh.ki.projekt.ast.ProgramElement;

/**
 *
 * @author adam
 */
public class Context implements Scope
{
    Scope parent;
    Set<ProgramElement> elements = new HashSet<>();
    Deque<Boolean> readonly = new ArrayDeque<>();

    public Context(Scope parent) 
    {
        assert parent!= null;
        this.parent = parent;
    }

    public void pushReadonly()
    {
        readonly.push(true);
    }

    public void popReadonly()
    {
        readonly.pop();
    }

    public boolean isReadonly()
    {
        return readonly.isEmpty() ||!readonly.peek();
    }

    @Override
    public boolean declare(ProgramElement elem)
    {
        if (!isReadonly())
            return elements.add(elem);
        return false;
    }

    @Override
    public boolean declare(ProgramElement elem, Scope current)
    {
        if (!isReadonly())
        {
            if (elem.isDeclared(current))
                return false;
            this.elements.add(elem);
            return true;
        }
        return false;
    }

    @Override
    public boolean declare(ProgramElement elem, Scope current, ProgramElement container)
    {
        if (!isReadonly())
        {
            boolean added = this.elements.add(elem);
            if (elem.isDeclared(current))
                return false;
            if (added)
                elem.setDeclared(current, container);
            return true;
        }
        return false;
    }

    @Override
    public boolean exists(ProgramElement elem)
    {
        boolean result =!isReadonly() && this.elements.contains(elem);
        if (result) return result;
        return parent.exists(elem);
    }

    @Override
    public Collection<ProgramElement> elements()
    {
        if (!isReadonly())
            return elements;
        return parent.elements();
    }
}
