    private static String applyUserInput(String pattern, String input, String templateContent) {
        Matcher matcher = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE).matcher(templateContent);
        while (matcher.find()) {
            String replacement = matcher.group();
            if (input == null || input.isEmpty()) {
                input = "";
            } 
            templateContent = matcher.replaceFirst(input);
        }
        return templateContent;
    }
