import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {

    // Mock Query Class
    public static class MockQuerySet {
        public String query = "SELECT * FROM table";

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            // It iterates over kwargs and appends them to the query structure
            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Pattern: Detect SQL keywords through Regular Expression (Regular Expression is case sensitive)
                String sqlKeywords = "[a-zA-Z0-9]+\\s(SELECT|FROM|WHERE|ORDER\\s+BY|LIMIT|AS)\\s";

                // Pattern: Detect SQL injection through Regular Expressions
                Pattern notAllowed = Pattern.compile(sqlKeywords);

                // Match the given keyword
                Matcher match = notAllowed.matcher(alias);

                // If valid, append alias to query
                // Else, return Exception with message
                if (!match.find()) {
                    // append alias to query
                    this.query += " AS " + alias;
                }
                else {
                    // throw exception
                    throw new IllegalArgumentException("Invalid alias");
                }
            }
            return this.query;
        }
    }
}

