public class AVLTree {
    private static String key(TreeNode<String> root) {
        if (root == null) {
            return "";
        }
        String key = "";
        if (root.left!= null) {
            key += "(" + key(root.left) + "_";
        }
        if (root.value.length()!= 0) {
            key += root.value;
        } else {
            key += "()";
        }
        if (root.right!= null) {
            key += "_" + key(root.right) + ")";
        }
