    private LinkedList<item> data;
    private int count;

    /**
     * Creates a <code>MyStack<item</code> object.
     */
    public MyStack() {
        data = new LinkedList<item>();
        count = 0;
    }

    public item pop() {
        item tempItem;
        if (count == 0) {
            return null;
        }

        tempItem = data.remove(count - 1);
        count--;
        return tempItem;
    }

    public void push(item itemToAdd) {
        data.add(itemToAdd, count);
        count++;
    }
