public class LinkedList<item> implements ListInterface<item> {
    private Node head;
    private int size;

    /**
     * Initializes a new <code>LinkedList</code> object.
     */
    public LinkedList() {
        head = null;
        size = 0;
    }

    public void add(item itemToAdd, int index) {
        if (index < 0 || index >= size) {
            return;
        } else if (index == 0) {
            head = new Node(itemToAdd, head); // insert new head node
            size++;
            return;
        }

        Node target = findNode(index - 1);
        Node newAdd = new Node(itemToAdd);
        newAdd.link = target.link;
        target.link = newAdd;
        size++;
    }

    public void clear() {
        head = null;
        size = 0;
    }

}

