import java.util.Stack; 
public class ReverseString {
    public static Stack<String> rstack = new Stack<String>();
    public static String reverse(String text) {
        String result = "";
        String toStack[] = text.split("`"); //splitting by `
        for (int i=0; i<toStack.length; i++) {
            rstack.push(toStack[i]); //push string into a stack
        }
        for (String str: rstack) {
            result += str + "`"; //and rejoin the stack by splitting by ``
        }
        return result;
    }
}


