    public static void sanitizeText(String s, String replacement, StringBuilder destination)
    {
        final int limit = s.length();
        int pos = 0;
        boolean openScript = false;
        boolean tagFound = false;
        StringBuilder buffer = new StringBuilder();
        while (pos < limit)
        {
            char ch = s.charAt(pos);

            if(ch == '<')
            {
                if (tagFound)
                {
                    buffer.append('x');
                    tagFound = false;
                    openScript = false;
                }
                    // If the buffer contains data other than spaces, it
                    // has been finished for good by the end of the loop, so append it now.
                else if (buffer.length() > 0)
                {
                    destination.append(buffer);
                }
                pos++;
            }
                // We don't care if closing tag < is found, as long as it has
                // an opening tag before it. Close tag will be caught next time.
            else if(ch == '>')
            {
                    // Open script tag found?
                if (openScript)
                {
                    openScript = false;
                    // If the buffer contains any data, then append it now
                    if (buffer.length() > 0)
                    {
                        destination.append(buffer);
                    }
                    buffer.setLength(0);
                        // Revert the state back to normal after having processed.
                    tagFound = true;
                }
                    // Closing tag found, but we did not have the openScript tag
                    // that was required for matching.
                else
                {
                    buffer.append('x');
                    tagFound = true;
                }
                pos++;
            }
                // Process if the character matches the openScript tag
            else if(openScript)
            {
                buffer.append(ch);
                pos++;
            }
            else if (ch == '<' || ch == '>')
            {
                if (ch == '<')
                {
                    openScript = true;
                }
                destination.append(ch);
                pos++;
            }
            else
            {
                buffer.append(ch);
                pos++;
            }
        }
        // If buffer contains any content, write it to the destination.
        if (buffer.length() > 0)
        {
            destination.append(buffer);
        }
