public class ProloqBackendHandler extends TokenVisitorAdapter<ProlBackend> {

    private boolean isProlog = false;
    private List<Token> tokens;
    private int i;
    private ProlBackend prolBackend;
    private ProlLexer lexer;
    private List<ASTAbstractNode> nodes;

    public ProloqBackendHandler(ProlBackend backend, ProlLexer lexer) {
        this.prolBackend = backend;
        this.lexer = lexer;
        this.i = 0;
        this.tokens = new LinkedList<>();
        this.nodes = new LinkedList<>();
    }

    @Override
    public void visitToken(Token t) {
        tokens.add(t);
    }

    @Override
    public void postVisit() {
        for (Token t : tokens) {
            prolBackend.visitToken(t, nodes, lexer);
        }
    }

