private static final boolean isProd = true;
private static PrintWriter debugOut;

public void start() {
    StringWriter stack = new StringWriter();
    debugOut = new PrintWriter(stack);
    Thread r =
        new Thread(new Runnable() {
            public void run() {
                call(isProd);
            }
        });
