public static String dumpInfo(final Exception exception, final String msg) {
		if (!System.getProperty("dumpEnabled", "")
				.equalsIgnoreCase("true")) {
			// Produción
			return "Exception info disabled in production mode";
		}
		if (exception!= null) {
			// Salvar el log de depuración
			try {
				// Poner en la pila del resultado de throw la información generada.
				StringWriter stackElement = new StringWriter();
				PrintWriter element = new PrintWriter(stackElement);
				exception.printStackTrace(element);
				element.flush();
				String s = stackElement.toString();
				if (msg!= null)
					return s + System.getProperty("line.separator") + msg;
				else
					return s;
			} catch (Throwable t) {
				// No salvar
			}
		}
		if (msg!= null) return msg;
		return "Error logging message";
	}
}
