    }
    public static boolean inShell() {
        return (new DebugTest()).getClass().getProtectionDomain().getCodeSource() == null;
    }
    public static boolean inJupyter() {
        return (new DebugTest()).getClass().getDeclaredClasses().length == 0;
    }
    public static boolean inDebug() {
        return System.getProperty("debug")!= null;
    }
