        // Vérifie s'il existe déjà un fichier avec le même nom
        if (fopr.checkFile(directory, filename))
        {
            /*
             * Renvoie un fichier avec le nom d'origine si le fichier est trouvé, 
             * cela permet à l'utilisateur de modifier le nom du fichier final.
             */
            getFileStream(directory, filename, true);
        }
        else
        {
            /*
             * Renvoie false dans le cas contraire, en écriture 
             * ou un fichier avec les données avec le nom de fichier, ce qui fait en sorte que l'utilisateur
             * voit immédiatement l'état du fichier.
             */
            return false;
        }

        return true;
    }
