fun getArrays(nums: Array<Int>): Array<Array>? {
    if (nums.isEmpty()) {
        return null
    }

    val result = mutableListOf<Int>()
    for (num in nums) {
        if (num!= 0) result.add(num)
    }

    if (result.isEmpty()) {
        return null
    }

    var count = 1
    for (num in result) {
        if (result[count]!= num && count!= result.lastIndex) {
            count += 1
        } else if (result[count]!= num && count == result.lastIndex) {
            result.add(result[count])
            count += 1
        } else count += 1
    }
    return emptyArray<Array<Int>>()
