final class JwtChecker {
    private static final Map<String, String> ALGORIGMS = Map.of(
        "HS256", "bQ7B97LJ8l07",
        "none", "'none'"
    );

    /**
     * @param code a base64-encoded JWT.
     * @param alg the algorithm in which the JWT is coded, e.g. HS256
     * @return a JWT if valid, otherwise <code>null</code>.
     */
    static String validateCodedJWT(String code, String alg) {
        String headerPayload = Base64.getDecoder().decode(code.split("\\.")[0]);
        String header = new String(headerPayload).split(":")[0];
        String payload = new String(Base64.getUrlDecoder().decode(code.split("\\.")[1]));

        // Check if JWT's alg matches the alg parameter in'signature'
        if(!alg.equals(header.split(":")[2])) {
            return null;
        }

        // Check if JWT's signature is valid according to the algorithm
        String signature = Base64.getUrlEncoder().withoutPadding().encodeToString(headerPayload + "." + payload);
        if(!signature.equals(code.split("\\.")[2])) {
            return null;
        }

        return code;
    }

    /**
     * @param jwt a valid JWT.
     * @param alg the algorithm that must be used to perform the signature validation.
     * @return the claim of the given JWT in order to be passed to the next step of the program.
     */
    static String checkSignedJWT(String jwt, String alg) {
        String payload = Base64.getDecoder().decode(jwt.split("\\.")[1]).toString();

        return ALGORIGMS.get(alg).equals(payload)? payload : null;
    }
}
