class Solution{

    private static final Map<String, Integer> mapAlg = new HashMap<String, Integer>();
    static {
        mapAlg.put("HS256", 256);
    }

    public static boolean isValidJWT(String tokenString) {
        if (tokenString == null || tokenString.length() == 0) {
            return false;
        }

        // separar el token en componentes
        Map<String, String> params = parseParams(tokenString);
        if (params.size() == 0) {
            return false;
        }

        // obtener las claves/valores necesarios
        final String alg = params.get("alg");
        final String header = Base64.getDecoder().decode(params.get("header"));
        //final String payload = params.get("payload");
        final String sign = params.get("sign");

        // validar que algoritmo soportado para obtener firma
        if (!mapAlg.containsKey(alg)) {
            return false;
        }
        // verificar si se firma el jwt con alg no nulo y se puede calcular la firma
        if (sign!= null) {
            if (params.containsValue(header)) {
                return false;
            }
            // calcular la firma del payload
            final int blockSize = mapAlg.get(alg) / 8;
            // comprobar la firma valida
            return Base64.getDecoder().decode(sign).length == blockSize;
        }
        // jwt valido
        return true;
    }

    /**
     * Parsea los parámetrso JSON en un mapa
     */
    private static Map<String, String> parseParams(final String json) {
        Map<String, String> result = new HashMap<String, String>();
        String[] parts = json.split("\\.");
        long i = 0;
        for (String str : parts) {
            String[] kv = str.split(",");
            result.put(kv[0], kv[1]);
            i = i + kv[kv.length - 1].length() + 1;
        }
        return result;
    }
