    int length = result.length;
    int noOfBlocks = length / blockSize;
    if(length % blockSize > 0) noOfBlocks++;
    byte[] newResult = new byte[result.length + (blockSize * (noOfBlocks - 1))];
    int start = 0;
    int finish = blockSize;
    for(int i=0; i<noOfBlocks; i++) {
