    public static HashMap<Character, Integer> countUniqueCharacters(String string, String delimiter) {
        // Memisahkan kata dengan spasi jadi array of words;
        String[] words = string.split("(?<=[\\p{L}\\p{Nd}])|[^\\p{L}\\p{Nd} ]+|(?=[\\p{L}\\p{Nd}])");
        // Menggabungkan words menjadi setiap karakternya
        char[] chars = string.chars().mapToObj(c -> (char)c).collect(StringBuffer::new, StringBuffer::append, StringBuffer::append).toString().toCharArray();

        // Menghitung jumlah munculnya untuk setiap karakter unik
        HashMap<Integer, Character> indexesCharacter = new HashMap<>(chars.length);
        for (char character: chars) {
            if (!indexesCharacter.containsKey(character))
                indexesCharacter.put(character, character);
        }

        // Membuat hashmap untuk menyimpan jumlah munculnya untuk setiap karakter unik
        HashMap<Character, Integer> countChars = new HashMap<>(indexesCharacter.size());
        for (Character chr: indexesCharacter.values()) {
            int count = (int)words.stream()
               .filter(word -> word.contains(String.valueOf(chr)))
               .count();

            countChars.put(chr, count);
        };

        // Mengurutkan hashmap dari karakter paling unik lebih awal
        return countChars.entrySet().stream().sorted((a, b) -> indexesCharacter.get(a.getKey()).compareTo(indexesCharacter.get(b.getKey()))).
            collect(toMap(c -> c.getKey(), c -> c.getValue(), (x, y) -> x, HashMap::new));

