package com.company;

public class Task implements Comparable<Task> {
    public final String code;
    public final int deadline;
    public final double importance;
    public static final String[] alphabeticOrder = {"A","C","E","F","H","J","K","M","N","P","R"};

    public Task(String code, int deadline, double importance) {
        this.code = code;
        this.deadline = deadline;
        this.importance = importance;
    }

    @Override
    public int compareTo(Task otherTask) {
        for (int i = 0; i < alphabeticOrder.length; i++) {
            if(alphabeticOrder[i].compareTo(code.substring(0, 1)) == 0 && alphabeticOrder[i].compareTo(otherTask.code.substring(0,1)) == 0) {
                return Integer.compare(deadline, otherTask.deadline);
            }
            if(deadline == otherTask.deadline){
                return Double.compare(importance, otherTask.importance);
            }
        }
        return 0;
    }

    @Override
    public String toString() {
        return code + " (" + deadline + "/" + importance + ")";
    }
}
