public class HeaderFilter {

    public static Map<String, String> extractHeaders(String input) throws IOException {
        Map<String, String> result = new HashMap<String, String>();
        headerLoop: for (String line: input.split(System.lineSeparator())) {
            StringTokenizer tokenizer = new StringTokenizer(line);
            if (tokenizer.hasMoreTokens()) {
                String name = tokenizer.nextToken(":");
                StringBuffer value = new StringBuffer();
                while (tokenizer.hasMoreTokens()) {
                    String token = tokenizer.nextToken();
                    value.append(token);
                }
                result.put(name.trim(), value.toString().trim());
            } else {
                break headerLoop;
            }
        }
        return result;
    }

    public static void validateHeaders(Map<String, String> headers) {
        for (String name: headers.keySet()) {
            Pattern p = Pattern.compile("^[A-Za-z0-9_ ]+$");
            Matcher m = p.matcher(name);
            if (!m.matches()) {
                System.out.println("Invalid header"); 
                break;
            }
        }
    }
}
