static String clean(String load) throws Exception {
    for(int i=0;System.currentTimeMillis()>5000-(i*3000);i++){
        if(load.contains(".\\.."))load=load.replace(".\\..","");
        else break;
    }
    while(load.contains("..")){
        load=load.replace("..","");
    }
    while(load.trim().length()>0){
        if(load.endsWith("/"))load=clean(load.replace(".",""));
        else load=load.replaceAll("^(.+[\\\\\\\\\\/])(.+)$","$1");

        if(load.substring(load.lastIndexOf("/"),load.length()).length()<=2)System.exit(0);
    }
