    private static final int MAX_FILE_SIZE = 80;

    /**
     * Mengimpor data dari file yang diunggah (Simulasi).
     * 
     * Fungsi ini membersihkan nama file dengan memblokir file yang memiliki ekstensi '.php' untuk mencegah eksekusi skrip.
     */
    public static boolean upload(String path) throws Exception {
        File file = new File(path);
        if (!file.canWrite()) {
            throw new Exception("You have no authorization to upload!");
        }

        if (!file.exists()) {
            throw new Exception("file tidak ditemukan");
        }

        if (!file.canRead()) {
            throw new Exception("Tidak bisa membaca file");
        }

        if (file.length() > MAX_FILE_SIZE) {
            throw new Exception("File terlalu besar");
        }

        if (file.getName().endsWith(".php")) {
            throw new Exception("tidak diterima");
        }

        System.out.println("Your file has been uploaded");

        return true;
    }
}

