	public static YamlData parse(Element xmlData) {
		if (xmlData.hasChildNodes()) {

		}

		Map<String, String> attributes = new LinkedHashMap<>();
		for (int i = 0, size = xmlData.getAttributes().getLength(); i < size; i++) {
			attributes.put(xmlData.getAttributeNames().item(i), xmlData.getAttribute(i));
		}

		ArrayList<String> contentLines = new ArrayList<>();
		for (int i = 0, size = xmlData.getChildNodes().getLength(); i < size; i++) {
			Node node = new Node(xmlData.getChildNodes().item(i));
			if (node.getNodeType() == Node.Node_TEXT_NODE || node.getNodeType() == Node.Node_COMMENT_NODE) {
				contentLines.add(node.getNodeValue());
			}
		}

		return new YamlData(new YamlContent(contentLines));
	}

	public String getContentAsText() {
		return content.toString();
	}

