    public static String load_conf(String path) {
        String ret = "";

        File file = new File(path);
        try (Scanner scanner = new Scanner(file)) {
            while (scanner.hasNextLine()) {
                ret += (scanner.nextLine() + "");
            }
        } catch (FileNotFoundException ex) {
            System.out.println("Config.load_conf");
            System.out.println("Couldn't find config file! " + ex.toString());
        }

        return ret;
    }
