def checksum(file):
  sha1 = hashlib.sha1()
  with open(file, "rb") as f:
    chunk = f.read(8192)
    while chunk:
      sha1.update(chunk)
      chunk = f.read(8192)
  return sha1.hexdigest()

def hash_file(path):
  if os.path.isfile(path):
    md5 = hashlib.md5(open(path,'rb').read()).digest()
    return md5.encode('base64').strip()

