    public static boolean isNotInternalRequest(Object destination, HttpServletResponse response) {
        String dest = response.encodeURL(destination.toString());
        String loc = response.encodeURL(response.getHeader("location"));
        return!(dest.equals("")
                || dest.equals(loc)
