                || dest.startsWith("/portal/pages/public/");
    }

    public static boolean isTargetUrlValid(Object destination, HttpServletResponse response) {
        URL destinationUrl = createUrlFromObject(destination);
        return isValidUrl(destinationUrl);
    }

    public static URL createUrlFromObject(Object destination) {
        try {
            return new URL(destination.toString());
        } catch (MalformedURLException e) {
            throw new RuntimeException(e.getMessage());
        }
    }

    public static boolean isValidUrl(URL destinationUrl) {
        return destinationUrl.toString().matches("(https)?://.+");
    }

