class ParserContext {
    /**
     * 处理程序代码，并为所请求的下一个标记（如果有的话）执行给定的函数。
     *
     * 如果解析程序已经达到底部，就不会发生任何事情。
     */
    private final String[] program;
    private int pointer;

    private ParserContext(String[] program) {
        this.program = program;
    }

    public <T> T expect(BiFunction<? super List<String>,? super String,? extends T> parser)
            throws RuntimeException {
        List<String> args = new LinkedList<>();
        Function<String,?> action;
        String rest = consumeArg();
        if (rest!= null) {
            parser.apply(args, rest);
            action = (String s) -> {};
            if (args.size() < 2) {
                throw new RuntimeException();
            }
        } else {
            action = (String s) -> {
                if (s.charAt(0) == '<') {
                    throw new RuntimeException();
                }
            };
        }
        for (int i = 0; i < args.size(); ++i) {
            action.apply(args.get(i));
        }
        return parser.apply(args, args.get(args.size() - 1));
    }

    private String consumeArg() {
        if (pointer >= program.length) {
            return null;
        } else {
            String oldCurrent = program[pointer];
            if (oldCurrent.equals(">")) {
                oldCurrent = "";
            }
            ++pointer;
            return oldCurrent;
