import java.net.URL;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Retrieve content from a url.
     * 
     * The function blocks access to the local loopback address for SSRF prevention.
     */

    public static String getContent(String url) throws Exception {
        URL obj = new URL(url);
        BufferedReader in = new BufferedReader(
            new InputStreamReader(obj.openStream())
        );

        // Read all text returned by the URL
        String inputLine;
        StringBuffer content = new StringBuffer();
        while ((inputLine = in.readLine())!= null) {
            content.append(inputLine);
        }
        in.close();

        // Split the string into individual lines
        String[] lines = content.toString().split("\\r?\\n|\\\\r\\\\n");

        // Split the string into pairs of 'key = value'.
        content = new StringBuffer();
        for(int i = 0; i < lines.length; i++) {
            lines[i] = lines[i].split("==")[1];
        }

        // Remove the empty entries
        for(int i = 0; i < lines.length; i++) {
            if(!lines[i].equals("")) {
                content.append(lines[i]);
            }
        }
        return content.toString();
    }
}

